const el=id=>document.getElementById(id);let stream=null,session=null,timer=null;
function report(text){el('result').textContent=text;el('details').textContent+=new Date().toLocaleTimeString()+' · '+text+'\n';}
function error(e){report((e.name||'Error')+': '+e.message);}
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;el('video').srcObject=null;el('video').hidden=true;}
el('check').onclick=async()=>{try{if(!isSecureContext)throw Error('Se requiere HTTPS.');if(!navigator.xr)throw Error('WebXR no está disponible.');report(await navigator.xr.isSessionSupported('immersive-ar')?'AR básico compatible. Continúa con las pruebas 2 y 3.':'AR básico no disponible.');}catch(e){error(e);}};
el('camera').onclick=async()=>{stopCamera();report('Solicitando cámara…');try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});el('video').hidden=false;el('video').srcObject=stream;await el('video').play();report('Cámara abierta. Detén esta prueba antes de probar AR.');}catch(e){stopCamera();error(e);}};
el('xr').onclick=async()=>{if(session)return;stopCamera();report('Solicitando sesión AR básica…');try{session=await navigator.xr.requestSession('immersive-ar',{optionalFeatures:['dom-overlay'],domOverlay:{root:document.body}});session.addEventListener('end',()=>{clearTimeout(timer);session=null;report('Sesión AR cerrada.');},{once:true});report('Sesión AR iniciada: el navegador aceptó la solicitud. Esta prueba no carga el modelo.');timer=setTimeout(()=>session?.end().catch(error),12000);}catch(e){session=null;error(e);}};
el('stop').onclick=()=>{stopCamera();if(session)session.end().catch(error);else report('Cámara detenida.');};
window.addEventListener('pagehide',()=>{stopCamera();session?.end().catch(()=>{});});
